sys_script_include.script:
var MANAssetRefQual = Class.create();
MANAssetRefQual.prototype = {
    initialize: function() {},

    //Created By : Shivam Dighe
    //Created On : 22/07/2026
    //Purpose : To filter the reference records to exclude the retired CIs and restricts to software packages if the asset type is software

    byAssetType: function(current) {
        var q = 'install_status!=7';
        if (current.asset_type == 'software')
            q += '^sys_class_name=cmdb_ci_spkg';
        return q;
    },


    type: 'MANAssetRefQual'
};
